    withContext(Dispatchers.IO) {
        val options = BitmapFactory.Options().apply {
            inJustDecodeBounds = true // قراءة الأبعاد فقط دون حجز أي بكسل في الذاكرة
        }
        context.contentResolver.openInputStream(uri)?.use {
            BitmapFactory.decodeStream(it, null, options)
        }

        options.inSampleSize = calculateInSampleSize(options, reqW, reqH) // تصغير الأبعاد
        options.inJustDecodeBounds = false
        options.inPreferredConfig = Bitmap.Config.HARDWARE // تخزين مباشر في ذاكرة الـ GPU

        context.contentResolver.openInputStream(uri)?.use {
            BitmapFactory.decodeStream(it, null, options)!!
        }
    }
